INSERT INTO public.dataset_sources (source_id, name, license, license_url, provenance_summary, is_released_practice_set, is_official_college_board, record_count) VALUES ('hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'https://creativecommons.org/licenses/by/4.0/', 'HDSAT practice items written against the publicly published SAT Suite domain/skill blueprint (collegeboard.org) and incorporating public datasets of SAT-style practice content. NOT official College Board material and NOT derived from any College Board test form.', FALSE, FALSE, 9149) ON CONFLICT (source_id) DO UPDATE SET name = EXCLUDED.name, license = EXCLUDED.license, license_url = EXCLUDED.license_url, provenance_summary = EXCLUDED.provenance_summary, is_released_practice_set = EXCLUDED.is_released_practice_set, is_official_college_board = EXCLUDED.is_official_college_board, record_count = EXCLUDED.record_count;
INSERT INTO public.dataset_sources (source_id, name, license, license_url, provenance_summary, is_released_practice_set, is_official_college_board, record_count) VALUES ('hdsat-benchmark-sim-1', 'HDSAT Benchmark Simulation Set A (Released Practice Form)', 'CC-BY-4.0', 'https://creativecommons.org/licenses/by/4.0/', 'HDSAT original practice items reserved for the HDSAT Benchmark Form A simulation. Deliberately tagged is_released_practice_set=true so students can exclude benchmark-simulation items while drilling in the Question Bank or Practice Rush. NOT official College Board material.', TRUE, FALSE, 7) ON CONFLICT (source_id) DO UPDATE SET name = EXCLUDED.name, license = EXCLUDED.license, license_url = EXCLUDED.license_url, provenance_summary = EXCLUDED.provenance_summary, is_released_practice_set = EXCLUDED.is_released_practice_set, is_official_college_board = EXCLUDED.is_official_college_board, record_count = EXCLUDED.record_count;
INSERT INTO public.dataset_sources (source_id, name, license, license_url, provenance_summary, is_released_practice_set, is_official_college_board, record_count) VALUES ('wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0/', 'Verbatim introductory extracts from English Wikipedia articles, retrieved 2026-11-02 through the MediaWiki API. Every item names its article and URL in its attribution. Question stems, choices and rationales are original to HDSAT.', FALSE, FALSE, 868) ON CONFLICT (source_id) DO UPDATE SET name = EXCLUDED.name, license = EXCLUDED.license, license_url = EXCLUDED.license_url, provenance_summary = EXCLUDED.provenance_summary, is_released_practice_set = EXCLUDED.is_released_practice_set, is_official_college_board = EXCLUDED.is_official_college_board, record_count = EXCLUDED.record_count;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-M29-01', 'HDSAT-RW-INF-M29-01', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'In a three-year study of restored tallgrass prairies, ecologists seeded half the plots with a mix of thirty native species and half with a mix of eight. The diverse plots established more slowly at first, but by the third year they produced about 40 percent more biomass during an experimental drought and supported twice as many specialist bee species. The researchers concluded that species diversity can improve both drought resilience and pollinator habitat, even when a diverse planting takes longer to establish.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Restored prairies establish more quickly when they are seeded with only eight native species."}, {"id": "B", "text": "A diverse native seed mix can improve drought resilience and pollinator habitat even when it establishes more slowly than a species-poor mix."}, {"id": "C", "text": "Specialist bee species prefer restored prairies that contain only eight plant species."}, {"id": "D", "text": "Drought biomass in restored prairies depends primarily on rainfall rather than on species richness."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-M29-02', 'HDSAT-RW-INF-M29-02', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Medieval portolan charts plotted coastlines and sailing routes with striking accuracy, and their rhumb lines radiate from compass roses. Yet no surviving chart records the local magnetic declination that navigators would have needed to convert a magnetic bearing into a true bearing. Because uncorrected magnetic bearings would produce growing errors on long voyages, historians infer that', 'Which choice most logically completes the text?', '[{"id": "A", "text": "portolan charts were copied directly from ancient Roman maps that already showed magnetic declination."}, {"id": "B", "text": "magnetic declination was too small in the medieval Mediterranean to affect a ship''s course."}, {"id": "C", "text": "chart makers must have used astronomical observations or other corrections that the surviving charts do not preserve."}, {"id": "D", "text": "medieval navigators avoided long voyages until magnetic declination was formally measured."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-M29-03', 'HDSAT-RW-INF-M29-03', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Literary critic Maya Chen argues that in the novel The House on the Quay, the narrator''s outward composure conceals acute anxiety. Chen notes that the narrator describes household routines in careful detail while avoiding every direct statement about the family''s financial collapse.', 'Which quotation from the novel would most directly support Chen''s claim?', '[{"id": "A", "text": "\"I smoothed the tablecloth and returned each spoon to its place, though I could hear my own pulse and twice set the sugar bowl beside the wrong cup.\""}, {"id": "B", "text": "\"The dining room wallpaper had been imported from Lisbon, and its blue medallions caught the afternoon light.\""}, {"id": "C", "text": "\"My brother preferred the garden in the early morning, when the servants had not yet opened the shutters.\""}, {"id": "D", "text": "\"We spoke of the weather and of a cousin''s wedding, and I slept soundly after they had gone.\""}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-INF-M29-04', 'HDSAT-RW-INF-M29-04', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'To reconstruct past mercury deposition in remote lakes, researchers collect sediment cores from lake bottoms. Mercury binds to organic particles that settle out of the water, so each dated layer of sediment preserves a record of the mercury present when that layer formed. By measuring mercury concentrations in successive layers, scientists can distinguish broad atmospheric deposition from local geological sources and track how deposition changed over centuries.', 'According to the text, why do researchers measure mercury in dated sediment layers?', '[{"id": "A", "text": "To identify the species of fish that lived in the lake during each period."}, {"id": "B", "text": "To determine how quickly organic particles sink to the lake bottom."}, {"id": "C", "text": "To measure the current mercury concentration of the lake water."}, {"id": "D", "text": "To reconstruct how mercury deposition changed over time."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-M29-01', 'HDSAT-RW-CRF-M29-01', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Reviewers often call the novelist''s prose _______: within a single paragraph she can move from tender lyricism to biting satire, and her narrators may be generous in one sentence and merciless in the next.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "monolithic"}, {"id": "B", "text": "mercurial"}, {"id": "C", "text": "didactic"}, {"id": "D", "text": "laconic"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-CRF-M29-02', 'HDSAT-RW-CRF-M29-02', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'For decades, scholars treated the Antikythera mechanism as a decorative astronomical showpiece. Then, in 2006, computed tomography revealed more than thirty interlocking bronze gears inside the corroded fragments. That discovery allowed researchers to model the device''s gear ratios and show that it could predict eclipses and track the positions of the sun and moon. The mechanism is now understood as a sophisticated calendar computer rather than an ornamental curiosity.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two ancient devices and argues that one is more accurate than the other."}, {"id": "B", "text": "It describes the materials used to build an object and explains how they were mined."}, {"id": "C", "text": "It presents a long-standing assumption and then explains how new evidence revised that assumption."}, {"id": "D", "text": "It lists the steps of an archaeological excavation and evaluates the training of its workers."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
