INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-ALG-M29-03', 'HDSAT-M-ALG-M29-03', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Algebra', 'Linear inequalities in one or two variables', 'Medium', 'multiple_choice', 'A delivery van has an empty mass of 2,400 kilograms and will carry identical boxes that each have a mass of 35 kilograms. A bridge has a posted mass limit of 3,200 kilograms for the loaded van.', 'What is the greatest number of boxes the van can carry across the bridge?', '[{"id": "A", "text": "$22$"}, {"id": "B", "text": "$23$"}, {"id": "C", "text": "$20$"}, {"id": "D", "text": "$24$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
