INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-M29-02', 'HDSAT-M-GEO-M29-02', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Right triangles and trigonometric ratios', 'Medium', 'multiple_choice', 'In a right triangle, one acute angle measures $30^\circ$ and the hypotenuse has length 14.', 'What is the length of the side opposite the $30^\circ$ angle?', '[{"id": "A", "text": "$7$"}, {"id": "B", "text": "$7\\sqrt{3}$"}, {"id": "C", "text": "$14\\sqrt{3}$"}, {"id": "D", "text": "$14$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('M-GEO-M29-03', 'HDSAT-M-GEO-M29-03', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Math', 'Geometry and Trigonometry', 'Volume and surface area', 'Easy', 'multiple_choice', 'A right circular cylinder has a radius of 3 centimeters and a height of 10 centimeters.', 'What is the volume of the cylinder, in cubic centimeters?', '[{"id": "A", "text": "$90\\pi$"}, {"id": "B", "text": "$30\\pi$"}, {"id": "C", "text": "$60\\pi$"}, {"id": "D", "text": "$900\\pi$"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-M29-01', 'B', ARRAY['B']::TEXT[], 'The passage''s central claim is that the thirty-species plots, despite slower early establishment, produced more biomass under drought and supported more specialist bees. The keyed choice captures both benefits and the trade-off.', '{"A": "The passage says the diverse plots established more slowly, not more quickly.", "C": "The diverse plots supported twice as many specialist bee species, so the opposite is true.", "D": "The study compared seed mixes during a drought; it did not claim rainfall outweighed species richness."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-M29-02', 'C', ARRAY['C']::TEXT[], 'The passage sets up a puzzle: the charts are accurate, but they do not record the declination needed to turn magnetic readings into true bearings. The most logical inference is that corrections existed in another form and were not written on the surviving charts.', '{"A": "The passage gives no evidence that Roman maps already recorded magnetic declination.", "B": "If declination were negligible, the passage would not describe cumulative errors on long voyages.", "D": "The passage says the charts were used for sailing routes, not that long voyages were avoided."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-M29-03', 'A', ARRAY['A']::TEXT[], 'The keyed quotation shows the narrator performing calm domestic order while betraying physical signs of panic: a racing pulse and a repeatedly misplaced object. That is exactly the gap between surface composure and hidden anxiety that Chen describes.', '{"B": "The wallpaper description supplies decorative detail but reveals no anxiety beneath composure.", "C": "The brother''s preference for the garden has no bearing on the narrator''s concealed fear.", "D": "Sound sleep and ordinary conversation suggest composure without underlying distress."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-INF-M29-04', 'D', ARRAY['D']::TEXT[], 'The passage explains that dated layers preserve mercury from the time each layer formed, which lets scientists track deposition over centuries and separate atmospheric from geological sources.', '{"A": "The text does not use sediment mercury to identify fish species.", "B": "Sinking speed is part of how the record forms, not the reason researchers measure it.", "C": "The cores record past deposition, not only the lake''s present mercury level."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-CRF-M29-01', 'B', ARRAY['B']::TEXT[], 'The sentence emphasizes rapid shifts in tone and temperament, so "mercurial" — changeable or volatile — is the precise fit.', '{"A": "\"Monolithic\" means uniform and unchanging, the opposite of the described shifts.", "C": "\"Didactic\" means intended to teach a moral lesson, which the sentence does not describe.", "D": "\"Laconic\" means using very few words, not changing tone abruptly."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-CRF-M29-02', 'C', ARRAY['C']::TEXT[], 'The text begins with the old view of the mechanism as a showpiece, then describes the CT scan evidence and the revised conclusion that it was a calendar computer.', '{"A": "Only one device is discussed; there is no comparison between two objects.", "B": "Materials and mining are not the subject of the passage.", "D": "The passage does not describe an excavation procedure or worker training."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-CRF-M29-03', 'A', ARRAY['A']::TEXT[], 'Chen accepts that wire copy supplied shared material, but he emphasizes local rewriting, commentary, and selection. That is a qualified response: shared inputs did not produce uniform output.', '{"B": "Chen says rural editors did subscribe, so this contradicts his account.", "C": "Chen acknowledges that the telegraph gave papers shared material; he does not deny any effect.", "D": "Chen argues that local editors shaped wire copy, which undercuts the claim that local styles disappeared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-EXP-M29-01', 'D', ARRAY['D']::TEXT[], 'The second sentence describes a later change in where mills could be built, so a time transition such as "Eventually" marks the shift from river power to steam power.', '{"A": "\"For example\" would present the steam-engine change as an illustration of river power, not a later development.", "B": "\"Similarly\" would suggest the second sentence continues the same pattern rather than replacing it.", "C": "\"In addition\" would imply both power sources were being discussed together, not a historical change."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-EXP-M29-02', 'B', ARRAY['B']::TEXT[], 'The keyed response states what Ball''s method changed — solubility and injectability — and explains why that mattered: it made a painful, unreliable treatment consistently deliverable.', '{"A": "Birth year and employer do not explain why the method was significant.", "C": "The later replacement of the treatment does not show what Ball''s method accomplished.", "D": "The oral-use detail is background and does not identify Ball''s contribution."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-SEC-M29-01', 'A', ARRAY['A']::TEXT[], 'The phrase "a converted nineteenth-century warehouse" is a nonessential appositive opened by a comma after "library," so it must be closed by a matching comma before "has served."', '{"B": "A semicolon would separate two independent clauses, but \"has served residents...\" has no subject of its own here.", "C": "A colon would introduce an explanation or list, not close the appositive.", "D": "A single dash would not match the comma that opened the appositive."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-SEC-M29-02', 'C', ARRAY['C']::TEXT[], 'The subject is the singular noun "collection"; the phrase "along with several unpublished photographs" does not change the subject. The singular past-tense verb "was" agrees with it.', '{"A": "\"Were\" is plural and does not agree with the singular subject \"collection.\"", "B": "\"Have been\" is plural and also shifts to the present perfect, which does not fit the 1998 date.", "D": "\"Are\" is plural and present tense, neither of which fits the subject and date."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-SEC-M29-03', 'B', ARRAY['B']::TEXT[], 'Two independent clauses need a semicolon before the conjunctive adverb "however," and the comma after "however" sets off the transition.', '{"A": "Without punctuation, the two independent clauses run together.", "C": "A comma before \"however\" creates a comma splice.", "D": "The semicolon is correct, but the comma after \"however\" is still required."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALG-M29-01', 'A', ARRAY['A']::TEXT[], 'Distribute: $6x - 15 = 4x + 7$. Subtract $4x$ from both sides: $2x - 15 = 7$. Add 15: $2x = 22$, so $x = 11$.', '{"B": "$4$ results from dropping the $-15$ when distributing.", "C": "$8$ results from adding 15 to only one side before dividing.", "D": "$22$ is the value of $2x$, not of $x$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALG-M29-02', '7', ARRAY['7', '7.0']::TEXT[], 'From $x - y = 3$, $x = y + 3$. Substitute into $3x + 2y = 19$: $3(y + 3) + 2y = 19$, so $5y + 9 = 19$ and $y = 2$. Then $x = 5$, and $x + y = 7$.', '{}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ALG-M29-03', 'A', ARRAY['A']::TEXT[], 'The loaded mass is $2{,}400 + 35b$, which must be at most $3{,}200$. Thus $35b \le 800$, so $b \le 22.857...$. The greatest whole number of boxes is 22.', '{"B": "23 boxes would add $805$ kilograms, exceeding the 800-kilogram allowance.", "C": "20 boxes is below the maximum, but the question asks for the greatest number.", "D": "24 boxes would add $840$ kilograms, which is over the limit."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ADV-M29-01', 'A', ARRAY['A']::TEXT[], 'Complete the square: $x^2 - 6x + 5 = (x - 3)^2 - 4$. The squared term is at least 0, so the minimum value is $-4$, reached at $x = 3$.', '{"B": "$-3$ is the $x$-coordinate of the vertex, not the minimum value.", "C": "$3$ has the wrong sign for the vertex''s $x$-coordinate and is not the minimum value.", "D": "$5$ is the $y$-intercept, not the vertex''s $y$-coordinate."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ADV-M29-02', 'B', ARRAY['B']::TEXT[], 'A 4 percent annual increase multiplies the population by $1 + 0.04 = 1.04$ each year, so the model is $12{,}000(1.04)^t$.', '{"A": "$1.4$ represents a 40 percent increase, not 4 percent.", "C": "$0.04$ alone would shrink the population to 4 percent of its previous size each year.", "D": "$1.004$ represents a 0.4 percent increase, ten times too small."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-ADV-M29-03', 'A', ARRAY['A']::TEXT[], 'First evaluate the inner function: $g(2) = 2^2 - 3 = 1$. Then $f(1) = 2(1) + 1 = 3$.', '{"B": "$1$ is $g(2)$, not the final composition.", "C": "$5$ results from evaluating $g(f(2))$ instead of $f(g(2))$.", "D": "$7$ results from using $2^2 + 3$ for $g(2)$."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-PSD-M29-01', 'A', ARRAY['A']::TEXT[], 'The discount makes the price $80(1 - 0.25) = 60$. Tax adds 10 percent of $60, or $6, for a total of $66.', '{"B": "$60$ is the discounted price before tax.", "C": "$68$ applies the discount and tax incorrectly, as though tax were on the original price and then discounted.", "D": "$70$ results from subtracting only $10 from the original price."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-PSD-M29-02', 'A', ARRAY['A']::TEXT[], 'There are $5 + 3 + 2 = 10$ marbles total. The 3 blue marbles are excluded, leaving $5 + 2 = 7$ favorable outcomes, so the probability is $7/10$.', '{"B": "$3/10$ is the probability of selecting a blue marble.", "C": "$7/3$ is greater than 1 and cannot be a probability.", "D": "$2/5$ is the probability of selecting a green marble."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-PSD-M29-03', 'A', ARRAY['A']::TEXT[], 'The five scores total $5(84) = 420$. The first four total $78 + 86 + 90 + 82 = 336$, so the fifth score is $420 - 336 = 84$.', '{"B": "$80$ would make the five-score total 416, for a mean of 83.2.", "C": "$82$ would make the total 418, for a mean of 83.6.", "D": "$88$ would make the total 424, for a mean of 84.8."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-M29-01', 'A', ARRAY['A']::TEXT[], 'Since $C = 2\pi r = 12\pi$, the radius is $6$. The area is $\pi r^2 = \pi(6)^2 = 36\pi$.', '{"B": "$6\\pi$ is the radius multiplied by $\\pi$, not the area.", "C": "$144\\pi$ squares the diameter rather than the radius.", "D": "$24\\pi$ uses the diameter instead of the radius in the area formula."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-M29-02', 'A', ARRAY['A']::TEXT[], 'In a right triangle, $\sin 30^\circ = \frac{\text{opposite}}{\text{hypotenuse}} = \frac{1}{2}$. Thus the opposite side is $14 \cdot \frac{1}{2} = 7$.', '{"B": "$7\\sqrt{3}$ is the length of the side adjacent to the $30^\\circ$ angle.", "C": "$14\\sqrt{3}$ multiplies the hypotenuse by $\\sqrt{3}$ without using the sine ratio.", "D": "$14$ is the hypotenuse, not the opposite side."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('M-GEO-M29-03', 'A', ARRAY['A']::TEXT[], 'The volume of a cylinder is $\pi r^2 h = \pi(3)^2(10) = 90\pi$.', '{"B": "$30\\pi$ uses $r h$ instead of $r^2 h$.", "C": "$60\\pi$ uses the diameter instead of the radius.", "D": "$900\\pi$ squares the height as well as the radius."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
